SELECT CodLivello.Ordine, FICHA11.[NUMERO DIPENDENT], FICHA11.COGNOME, FICHA11.NOME, FICHA11.[INDIRIZZO DI RESID], FICHA11.[COMUNE RESIDENZA], FICHA11.[PROV# DI RESIDENZA], FICHA11.CAP, FICHA11.[COMUNE NASCITA], FICHA11.[PROV# DI NASCITA], FICHA11.[DATA NASCITA], FICHA11.[CODICE FISCALE], CodStatoCivile.StatoCivile, FICHA11.[DATA ASSUNZIONE], FICHA11.[NUMERO MATRICOLA], FICHA11.[COD#C#D#COSTO (4 NUMERI ES#0600)], CentroCosto.DESCRI, FICHA11.[DATA CESSAZIONE], CodStudio.Titolo, FICHA11.[DATA ASSUNZIONE GRUPPO], FICHA11.[CAT BRX], FICHA11.[CODICE LIVELLO], CodLivello.DESCRI, FICHA11.[DESCR#MANSIONE], FICHA11.[DATA PASS#QUALIF], Sindacato.NomeOrganizzazione, codTB1.DescTB1, FICHA11.SQUADRA, FICHA11.[% MAGG# C#U#], FICHA11.[RETRIB#BAS], FICHA11.CONTINGENZ, FICHA11.SUPERMINIM, FICHA11.[SUP#REP#OR], FICHA11.[SCATTI ANZ], FICHA11.[CSCI AD P#], FICHA11.[PREMIO PRO], FICHA11.[EX SCATTI], FICHA11.[MANC#MENSA], FICHA11.[IND#FISSA], FICHA11.MIAZ, FICHA11.[I#R#IND], FICHA11.[ECC#CON#AN], FICHA11.[EL#MAGG# 12%], FICHA11.[IND#SPEC#], FICHA11.[TOTALE RETRIBUZ#], FICHA11.[ART# 27  VOCE 2090], FICHA11.[TFR TEORICO TOTALE], FICHA11.[ACCONTO FISSO  VOCE 702], FICHA11.[CODICE PAGAMENTO], FICHA11.[DOMIC#BANCARIO], FICHA11.[COD#ABI BANCA DIP#], FICHA11.[COD#CAB FILIAIE DI], FICHA11.[NUMERO CONTO DIP]
FROM Sindacato RIGHT JOIN ((CodLivello RIGHT JOIN (CodStudio RIGHT JOIN (CentroCosto RIGHT JOIN (CodStatoCivile RIGHT JOIN FICHA11 ON CodStatoCivile.Codice = FICHA11.[COD#STATO CIVILE]) ON CentroCosto.CODICE = FICHA11.[COD#C#D#COSTO (4 NUMERI ES#0600)]) ON CodStudio.Codice = FICHA11.[COD#TITOLO DI STUD]) ON CodLivello.CODICE = FICHA11.[CODICE LIVELLO]) LEFT JOIN codTB1 ON FICHA11.[RIC# TAB# TB1] = codTB1.CodiceTB1) ON Sindacato.CODICE = FICHA11.[COD#TRATT#SINDAC]
ORDER BY FICHA11.COGNOME;
